FILLER = "near-miss arithmetic slip"   # item._fillers; server/progress.FILLER files it as a slip
# a reason that singles one option out cannot be true of two
SINGLES_OUT = re.compile(r"\b(?:furthest|farthest|greatest|largest|smallest|highest|lowest|fewest|the most|the least)\b", re.I)

def valued(item) -> bool:
    """Numeric options that are values of the answer, not labels such as years."""
    if not all(numeral(o) is not None for o in item.choices):
        return False
    shown, key = numeral(displayed_answer(item)), float(item.key)
    return any(math.isclose(shown, k, rel_tol=1e-6, abs_tol=1e-9) for k in (key, key * 100))

def repeated_reasons(item, report) -> None:
    """MC only: a grid-in names just the value typed. Two options may share a reason
    true of both; they may not share one computation, or one superlative."""
    by = {}
    for i, (option, reason) in enumerate(zip(item.choices, item.reasons)):
        if reason and "ABCD"[i] != item.answer:
            by.setdefault(" ".join(reason.lower().split()), []).append(option)
    fillers = len(by.pop(FILLER, []))
    if fillers >= 2:
        report("filler_majority", f"{fillers} of 3 wrong options are unnamed near-misses: {item.choices}")
    for reason, options in by.items():
        if len(options) > 1 and (valued(item) or SINGLES_OUT.search(reason)):
            report("repeated_reason", f"{reason} <- {', '.join(options)}")
            return

